package hagrid.core.routing.sections;
import java.util.*;import hagrid.core.routing.*;import hagrid.core.util.Delivery;import org.matsim.api.core.v01.*;import org.matsim.api.core.v01.network.Link;import org.matsim.core.network.NetworkUtils;import org.matsim.core.population.routes.RouteUtils;import org.matsim.freight.carriers.*;import org.matsim.vehicles.*;
class FixedOutOfHomeBindingTest {
 static void check(boolean x,String msg){if(!x)throw new AssertionError(msg);} static void rejects(Runnable r,String msg){try{r.run();throw new AssertionError(msg);}catch(IllegalArgumentException expected){}}
 @org.junit.jupiter.api.Test void homeSplitDoesNotInventLockerPositionOrReverse(){
 var n=NetworkUtils.createNetwork();var a=NetworkUtils.createAndAddNode(n,Id.createNodeId("a"),new Coord(0,0));var b=NetworkUtils.createAndAddNode(n,Id.createNodeId("b"),new Coord(100,0));NetworkUtils.createAndAddLink(n,Id.createLinkId("f"),a,b,100,10,1000,1);NetworkUtils.createAndAddLink(n,Id.createLinkId("depot"),b,a,100,10,1000,1);var road=new PreparedHaltCatalog.Road("a","b",100,100,List.of(new PreparedHaltCatalog.Point(0,0),new PreparedHaltCatalog.Point(100,0)));
 var home=new PreparedHaltCatalog.Job("home","f",List.of(new PreparedHaltCatalog.Approach("f",.5)),"HOME","home");
 var locker=new PreparedHaltCatalog.Job("locker","f",List.of(new PreparedHaltCatalog.Approach("f",1)),"PARCEL_LOCKER_EXISTING","ooh:1","f",new PreparedHaltCatalog.Point(20,40),null,List.of(),true);
 var roads=SplitRoadNetworkBuilder.build(n,new PreparedHaltCatalog("c",Map.of("f",road),List.of(home,locker),"f"));var last=roads.children().get(Id.createLinkId("f")).getLast();check(roads.jobApproaches().get("locker").size()==1 && roads.jobApproaches().get("locker").getFirst().haltLinkId().equals(last),"fixed stop must bind last child");
 var c=CarriersUtils.createCarrier(Id.create("c",Carrier.class));var t=VehicleUtils.createVehicleType(Id.create("v",VehicleType.class),"car");t.getCapacity().setOther(10);t.getCostInformation().setCostsPerMeter(0.0);t.getCostInformation().setCostsPerSecond(0.0);t.getCostInformation().setFixedCost(5.0);c.setCarrierCapabilities(CarrierCapabilities.Builder.newInstance().addVehicle(CarrierVehicle.newInstance(Id.createVehicleId("v"),Id.createLinkId("depot"),t)).build());
 for(String id:List.of("home","locker")){var s=CarrierService.Builder.newInstance(Id.create(id,CarrierService.class),Id.createLinkId("f"),1).setServiceDuration(7).setServiceStartingTimeWindow(TimeWindow.newInstance(100,200)).build();s.getAttributes().putAttribute("stop_id",id.equals("home")?"home":"ooh:1");s.getAttributes().putAttribute("coord",id.equals("home")?new Coord(50,0):new Coord(20,40));s.getAttributes().putAttribute("carrierMode",id.equals("home")?Delivery.DeliveryMode.HOME:Delivery.DeliveryMode.PARCEL_LOCKER_EXISTING);CarriersUtils.addService(c,s);}
 var catalog=SectionCatalogBuilder.build(c,roads,100,10);check(catalog.sections().size()==2,"different stop kinds remain separate");
 SectionRoadCosts costs=new SectionRoadCosts(){public SectionLeg leg(Id<Link>x,Id<Link>y,VehicleType v){return new SectionLeg(10,10,0);}public RoadLeg materialize(Id<Link>x,Id<Link>y,double time,Vehicle v){var r=RouteUtils.createLinkNetworkRouteImpl(x,y);r.setVehicleId(v.getId());r.setDistance(10);r.setTravelTime(10);return new RoadLeg(r,10,10,0);}public String fingerprint(){return "test";}};
 var result=new CarrierOptimizationService().searchSections(catalog,roads.network(),costs,300,300,0,4711,new SectionSearchPolicy(2,.25,.4));var expanded=SectionPlanExpander.expand(result,catalog,costs);check(expanded.bindings().size()==2 && expanded.bindings().get("locker").equals(last),"both served, locker fixed");check(SectionBindingValidator.validatePlan(catalog,expanded.carrier(),expanded.plan(),expanded.bindings()).isEmpty(),"valid plan");
 var changed=CarriersUtils.createCarrier(Id.create("c",Carrier.class));changed.setCarrierCapabilities(c.getCarrierCapabilities());for(var s:c.getServices().values())CarriersUtils.addService(changed,s);changed.getServices().get(Id.create("locker",CarrierService.class)).getAttributes().putAttribute("carrierMode",Delivery.DeliveryMode.HOME);rejects(()->SectionCatalogBuilder.build(changed,roads,100,10),"fixed HOME rejected");
 System.out.println("PASS mixed home and OOH fixed link");
 }
}
